"""Small, lossless stdlib compression codec.

The public ``enc``/``dec`` (and ``encode``/``decode``) functions accept bytes-like
objects or text. The representation is self-describing and preserves whether the
input was text or bytes.
"""
from __future__ import annotations

import zlib

_MAGIC = b"FZ1"
_RAW = 0
_ZLIB = 1


def enc(value):
    """Encode text or bytes-like data into a reversible byte string."""
    if isinstance(value, str):
        kind, raw = 1, value.encode("utf-8")
    elif isinstance(value, (bytes, bytearray, memoryview)):
        kind, raw = 0, bytes(value)
    else:
        raise TypeError("enc expects str or a bytes-like object")

    packed = zlib.compress(raw)
    if len(packed) < len(raw):
        flag, payload = _ZLIB, packed
    else:
        flag, payload = _RAW, raw
    return _MAGIC + bytes((kind, flag)) + payload


def dec(blob):
    """Decode a value produced by :func:`enc`, rejecting malformed frames."""
    if not isinstance(blob, (bytes, bytearray, memoryview)):
        raise TypeError("dec expects a bytes-like object")
    blob = bytes(blob)
    if len(blob) < len(_MAGIC) + 2 or blob[:3] != _MAGIC:
        raise ValueError("invalid encoded data")
    kind, flag = blob[3], blob[4]
    payload = blob[5:]
    if kind not in (0, 1) or flag not in (_RAW, _ZLIB):
        raise ValueError("invalid encoded data")
    try:
        raw = zlib.decompress(payload) if flag == _ZLIB else payload
    except zlib.error as exc:
        raise ValueError("invalid compressed payload") from exc
    if kind == 1:
        try:
            return raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError("invalid text payload") from exc
    return raw


encode = enc
decode = dec

