"""Lossless compression for byte strings using the Python standard library."""
import lzma


def enc(data):
    """Compress bytes when that makes the representation smaller."""
    if not isinstance(data, bytes):
        data = bytes(data)
    compressed = lzma.compress(data, preset=9)
    return compressed if len(compressed) < len(data) else data


def dec(data):
    """Decompress an encoded value, or return it unchanged if stored raw."""
    try:
        return lzma.decompress(data)
    except (lzma.LZMAError, ValueError, EOFError):
        return data


